import json
from collections import deque

def flood_fill_bg(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1

    bg_color = max(counts, key=lambda x: counts[x])

    reachable = [[False]*w for _ in range(h)]
    queue = deque()

    # Add boundary bg cells to queue
    for c in range(w):
        if grid[0][c] == bg_color:
            queue.append((0, c))
            reachable[0][c] = True
        if grid[h-1][c] == bg_color:
            queue.append((h-1, c))
            reachable[h-1][c] = True

    for r in range(1, h-1):
        if grid[r][0] == bg_color:
            queue.append((r, 0))
            reachable[r][0] = True
        if grid[r][w-1] == bg_color:
            queue.append((r, w-1))
            reachable[r][w-1] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not reachable[nr][nc]:
                if grid[nr][nc] == bg_color:
                    reachable[nr][nc] = True
                    queue.append((nr, nc))

    return reachable, bg_color

def apply_rule(grid):
    h, w = len(grid), len(grid[0])
    reachable, bg_color = flood_fill_bg(grid)
    result = [row[:] for row in grid]
    fg_color = None
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    fg_color = [v for v in counts if v != bg_color][0]

    for r in range(h):
        for c in range(w):
            if not reachable[r][c] and grid[r][c] == bg_color:
                result[r][c] = 4
    return result, fg_color

